<script setup>
import {ref,watch,onMounted} from 'vue'
import {api} from '../../services/api.js'
const props=defineProps({policy:Object,rules:Array,editable:Boolean}),emit=defineEmits(['draft'])
const error=ref(''),exceptions=ref({items:[],total:0}),hygiene=ref({items:[]}),templates=ref([]),nodes=ref([]),template=ref('dns'),endpoints=ref([]),ports=ref(''),busy=ref(false),page=ref(1),state=ref('all'),reason=ref(''),date=ref(''),showForm=ref(false)
const form=ref({ruleId:'',owner:'',justification:'',requestRef:'',reviewAt:'',expiresAt:''})
async function load(){try{const [e,h]=await Promise.all([api('/rule-exceptions?'+new URLSearchParams({policyId:props.policy.id,page:page.value,pageSize:25,state:state.value})),api(`/policies/${props.policy.id}/hygiene`)]);exceptions.value=e;hygiene.value=h}catch(e){error.value=e.message}}
async function save(){busy.value=true;error.value='';try{await api(`/policies/${props.policy.id}/exceptions`,{method:'POST',body:{...form.value,versionId:props.policy.current_version_id,reviewAt:new Date(form.value.reviewAt).toISOString(),expiresAt:form.value.expiresAt?new Date(form.value.expiresAt).toISOString():null}});showForm.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function review(e,action){busy.value=true;error.value='';try{await api(`/rule-exceptions/${e.id}/review`,{method:'POST',body:{action,reason:reason.value,...(action==='recertify'?{reviewAt:new Date(date.value).toISOString()}: {})}});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function retirement(e){try{const preview=await api(`/rule-exceptions/${e.id}/retirement-preview`);emit('draft',preview.graph)}catch(e){error.value=e.message}}
async function useTemplate(){busy.value=true;error.value='';try{const preview=await api('/policy-templates/preview',{method:'POST',body:{templateId:template.value,endpointNodeIds:endpoints.value,...(ports.value?{ports:ports.value.split(',').map(v=>Number(v.trim()))}:{})}});emit('draft',preview.graph)}catch(e){error.value=e.message}finally{busy.value=false}}
watch(()=>props.policy.id,()=>{page.value=1;load()})
onMounted(async()=>{await load();try{templates.value=await api('/policy-templates');const n=await api('/nodes');nodes.value=n.items||n}catch(e){error.value=e.message}})
</script>
<template><section class="panel glass"><div class="panel-title"><h2>Rule lifecycle and templates</h2><button class="button secondary" @click="load">Refresh</button></div><div class="body"><p v-if="error" class="error-msg" role="alert">{{error}}</p><details v-if="editable"><summary>Build a scoped service template</summary><form class="fields" @submit.prevent="useTemplate"><label>Template<select v-model="template"><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}} · v{{t.version}}</option></select></label><label>Destination assets<select v-model="endpoints" multiple required><option v-for="n in nodes" :key="n.id" :value="n.id">{{n.hostname}}</option></select></label><label>Backup / management ports<input v-model="ports" placeholder="Explicit ports, comma separated"></label><p>Endpoints need the matching reviewed application role. Templates create a Windows policy draft for review and simulation.</p><button class="button secondary" :disabled="busy">Load template draft</button></form></details><div class="actions"><select v-model="state" aria-label="Exception review filter" @change="page=1;load()"><option value="all">All exceptions</option><option value="due">Review due</option><option value="expired">Expired</option><option value="retirement-requested">Retirement requested</option></select><button v-if="editable" class="button secondary" @click="showForm=!showForm">Add exception record</button></div><form v-if="showForm" class="fields" @submit.prevent="save"><label>Saved policy rule<select v-model="form.ruleId" required><option value="">Select rule</option><option v-for="r in rules" :key="r.sourceNodeId" :value="r.sourceNodeId">{{r.name}}</option></select></label><label>Owner<input v-model="form.owner" required maxlength="200"></label><label>Justification<textarea v-model="form.justification" required maxlength="4000"></textarea></label><label>Linked request<input v-model="form.requestRef" maxlength="500"></label><label>Review date<input v-model="form.reviewAt" type="datetime-local" required></label><label>Expiry (optional)<input v-model="form.expiresAt" type="datetime-local"></label><button class="button primary" :disabled="busy">Save record</button></form><p class="muted">Expiry requires reviewed withdrawal and verified deployment. No observed use does not prove that a rule is unused.</p><div v-if="editable" class="actions"><input v-model="reason" placeholder="Reason for review decision" aria-label="Exception review reason" maxlength="2000"><label>Next review<input v-model="date" type="datetime-local"></label></div><div class="table-wrap"><table><thead><tr><th>Rule</th><th>Owner</th><th>Review</th><th>Expiry</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="e in exceptions.items" :key="e.id"><td>{{e.rule_id}}<small>{{e.justification}}</small></td><td>{{e.owner}}</td><td>{{new Date(e.review_at).toLocaleString()}}</td><td>{{e.expires_at?new Date(e.expires_at).toLocaleString():'None'}}</td><td>{{e.stale?'Policy changed':e.status}}<small v-if="e.expired">Expired — withdrawal pending</small></td><td v-if="editable"><button class="button small secondary" :disabled="busy||e.stale||!reason.trim()||!date" @click="review(e,'recertify')">Recertify</button><button class="button small secondary" :disabled="busy||e.stale||!reason.trim()" @click="review(e,'retire')">Request retirement</button><button v-if="e.status==='retirement-requested'" class="button small secondary" @click="retirement(e)">Review withdrawal draft</button></td></tr><tr v-if="!exceptions.items.length"><td colspan="6">No exception records.</td></tr></tbody></table></div><div class="actions"><span>{{exceptions.total}} records · Page {{page}}</span><button class="button secondary" :disabled="page===1" @click="page--;load()">Previous</button><button class="button secondary" :disabled="page*25>=exceptions.total" @click="page++;load()">Next</button></div><h3>Rule hygiene candidates</h3><p v-if="!hygiene.items.length" class="muted">No exact duplicate or broad allow candidates found. This does not establish complete rule coverage.</p><ul><li v-for="(h,i) in hygiene.items" :key="i">{{h.ruleId}} — {{h.kind}}: {{h.reason}}</li></ul></div></section></template>
<style scoped>.body{padding:16px;min-width:0}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.fields label{display:grid;gap:6px}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:16px 0}.table-wrap{overflow:auto;max-width:100%}table{width:100%}td{max-width:40ch;overflow-wrap:anywhere}small{display:block;color:var(--muted)}@media(max-width:800px){.fields{grid-template-columns:1fr}}</style>
